   157	    private Payment createCardPayment(Order order, User user, CardPaymentRequestDto requestDto) {
   158	        Instant start = Instant.now();
   159	        try {
   160	            log.info("카드 결제 처리 시작: 주문ID={}, 결제정보ID={}",
   161	                    order.getId(), requestDto.getPaymentInfoId());
   162	
   163	            // 1. PaymentInfo 조회
   164	            PaymentInfo paymentInfo;
   165	            try {
   166	                paymentInfo = paymentInfoQueryService.getPaymentInfoEntity(user.getEmail(), requestDto.getPaymentInfoId());
   167	                if (paymentInfo == null) {
   168	                    throw new PaymentInfoNotFoundException("결제 정보 ID: " + requestDto.getPaymentInfoId() + "를 찾을 수 없습니다.");
   169	                }
   170	            } catch (PaymentException e) {
   171	                throw e; // 이미 PaymentException이면 그대로 전파
   172	            } catch (Exception e) {
   173	                throw new PaymentInfoNotFoundException("결제 정보 조회 중 오류가 발생했습니다.", e);
   174	            }
   175	
   176	            // 2. 결제 요청 생성
   177	            Map<String, Object> response;
   178	            try {
   179	                response = portOneApiClient.processCardPayment(paymentInfo, requestDto.getPaidAmount());
   180	            } catch (PaymentException e) {
   181	                throw e; // 이미 PaymentException이면 그대로 전파
   182	            } catch (Exception e) {
   183	                throw new PaymentApiException("카드 결제 요청 중 오류가 발생했습니다: " + e.getMessage());
   184	            }
   185	
   186	            // 3. CardPayment 생성 및 저장
   187	            CardPayment cardPayment = CardPayment.builder()
   188	                    .cardNumber(paymentInfo.getCardNumber())
   189	                    .cardPassword(paymentInfo.getCardPassword())
   190	                    .cardExpiration(paymentInfo.getExpirationDate())
   191	                    .birthDate(paymentInfo.getBirthDate())
   192	                    .cardType((String) response.get("card_name"))
   193	                    .paidAmount(requestDto.getPaidAmount())
   194	                    .impUid((String) response.get("imp_uid"))
   195	                    .receiptUrl((String) response.get("receipt_url"))
   196	                    .pgProvider((String) response.get("pg_provider"))
   197	                    .pgTid((String) response.get("pg_tid"))
   198	                    .build();
   199	
   200	            cardPayment.assignOrder(order);
   201	            cardPayment.assignUser(user);
   202	
   203	            if ("success".equals(response.get("status"))) {
   204	                cardPayment.updateStatus(PaymentStatus.PAID);
   205	                cardPayment.updateSuccessStatus(true); // 결제 성공
   206	            }
   207	
   208	            CardPayment savedPayment = (CardPayment) paymentRepository.save(cardPayment);
   209	            log.info("카드 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
   210	                    order.getId(), savedPayment.getId(), savedPayment.getStatus());
   211	
   212	            // 처리 시간 로깅
   213	            Instant end = Instant.now();
   214	            Duration duration = Duration.between(start, end);
   215	            log.debug("카드 결제 처리 시간: {}ms", duration.toMillis());
   216	
   217	            return savedPayment;
   218	        } catch (PaymentException e) {
